/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        foundDdOpts = { showOn: "both", buttonText: "달력", buttonImage: "/images/common/icn_calendar.gif", buttonImageOnly: true, changeMonth: true, changeYear: true, showButtonPanel: false, yearRange: 'c-100:c+10' };

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":1
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf05000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.reg_button = $c.util.getComponent('reg_button');
        scwin.init_fillGen();
        scwin.init_conds();
        scwin.init_datefmt_cal_foundDd();
        scwin.init_datefmt_cal_chgApplDd1();
        scwin.init_datefmt_cal_chgApplDd2();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf05000.onpageload' });
    }
};

