/**
 * @method
 * @name tx_chk_frm
 * @description chk frm 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_chk_frm = async function (action) {
    const sbmOptions = {
        id: "tx_chk_frm",
        method: "post",
        action: action ?? "/corp/corp.do?method=corpNewReqSave",
        ref: "dma_chkFrmReq",
        target: "dlt_comAttrTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_checkUsrId
 * @description check Usr Id 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_checkUsrId = async function () {
    const sbmOptions = {
        id: "tx_fn_checkUsrId",
        method: "post",
        action: "/corp/register.do?method=searchUsrId",
        ref: "dma_checkUsrIdReq",
        target: "dlt_comAttrTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

