    if ($c.str.getByteLength($c.util.getComponent('ipt_cntrCd').getValue()) === 0) {
        await $c.win.alert("국가코드가 없습니다.");
        $c.util.getComponent("ipt_cntrCd").focus();
    } else {
        if ($c.util.getComponent('ipt_cntrCd').getValue()=== "410") {
            if ($c.util.getComponent('ipt_corpRegNo1').getValue().length === 6) {
                if ($c.util.getComponent('ipt_corpRegNo2').getValue().length !== 7) {
                    $c.util.getComponent("ipt_corpRegNo2").focus();
                }
                if ($c.util.getComponent('ipt_corpRegNo2').getValue().length === 7) {
                    $c.util.getComponent("ipt_bzRegNo1").focus();
                }
            }
        } else {
            await $c.win.alert("외국국적의 발행기관은 법인등록번호를 선택할 수 없습니다.");
        }
    }
};

