            }
        }
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo').getValue()) === 0) {
            await $c.win.alert("담당자 휴대전화번호를 입력하세요.");
            $c.util.getComponent("ipt_encrypCellphoneNo").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_chrgTelNo').getValue()) === 0) {
            await $c.win.alert("담당자 전화번호를 입력하세요.");
            $c.util.getComponent("ipt_chrgTelNo").focus();
            return false;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue()) === 0) {
        await $c.win.alert("회사담당자 이메일을 입력하세요.");
        $c.util.getComponent("ipt_encrypChrgEmail1").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue()) === 0) {
        await $c.win.alert("회사담당자 이메일을 입력하세요.");
        $c.util.getComponent("ipt_encrypChrgEmail2").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name chk_frm
 * @description chk frm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_frm = async function () {
    const fm = (document.JLDINF05000 || { elements: [] });
    if ($c.util.getComponent('ipt_cntrCd').getValue()=== '410') {
        $c.util.getComponent("ipt_telNo").setValue($c.util.getComponent('ipt_telNo1').getValue()+ "-" + $c.util.getComponent('ipt_telNo2').getValue()+ "-" + $c.util.getComponent('ipt_telNo3').getValue());
        $c.util.getComponent("ipt_chrgTelNo").setValue($c.util.getComponent('ipt_chrgTelNo1').getValue()+ "-" + $c.util.getComponent('ipt_chrgTelNo2').getValue()+ "-" + $c.util.getComponent('ipt_chrgTelNo3').getValue());
        $c.util.getComponent("ipt_encrypCellphoneNo").setValue($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo2').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo3').getValue());
        $c.util.getComponent("ipt_chrgFaxNo").setValue($c.util.getComponent('ipt_chrgFaxNo1').getValue()+ "-" + $c.util.getComponent('ipt_chrgFaxNo2').getValue()+ "-" + $c.util.getComponent('ipt_chrgFaxNo3').getValue());
        $c.util.getComponent("ipt_chrgInnrNo").setValue($c.util.getComponent('ipt_chrgInnrNo1').getValue());
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue().trim()) > 0 && $c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue().trim()) > 0) {
        $c.util.getComponent('dma_chkFrmReq').set('encrypChrgEmail', $c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ "@" + $c.util.getComponent('ipt_encrypChrgEmail2').getValue());
    }
    if (!await scwin.dataValidation()) {
        return;
    }
    if (!$c.str.isEmail($c.util.getComponent('dma_chkFrmReq').get('encrypChrgEmail'))) {
        await $c.win.alert("이메일 주소 형식이 아닙니다.");
        $c.util.getComponent("ipt_encrypChrgEmail1").focus();
        return;
    }
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }
    if (document.infoIframe.getComponentById("perInfo1").checked === false) {
        await $c.win.alert("개인정보 처리방침에 동의해 주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (document.infoIframe.getComponentById("perInfo2").checked === false) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해 주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (document.infoIframe.getComponentById("perInfo3").checked === false) {
        await $c.win.alert("표준코드 부여 및 관리 서비스 이용 약관에 동의해 주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (await $c.win.confirm("입력된 이메일을 확인해주세요.\n\n이메일 : " + $c.util.getComponent('ipt_encrypChrgEmail').getValue() + "\n\n신청하시겠습니까?")) {
        scwin.reg_button.setStyle("display", "none");
        fm.target = '_self';
        fm.method = 'post';
        await scwin.tx_chk_frm('/corp/corp.do?method=corpNewReqSave');
    }
};

