/**
 * @method
 * @name chgSelectIsurEngNm
 * @description chg Select Isur Eng Nm 처리
 * @returns {void}
 * @hidden N
 */
scwin.chgSelectIsurEngNm = function () {
    const temp = $("#slc_selectIsurEngNm option:checked").val();
    if (temp !== "" && temp !== "7") {
        $c.util.getComponent('ipt_isurEngNm2').setValue($("#slc_selectIsurEngNm option:checked").text());
        (($c.util.getComponent('ipt_isurEngNm2')) && ($c.util.getComponent('ipt_isurEngNm2')).setReadOnly ? ($c.util.getComponent('ipt_isurEngNm2')).setReadOnly((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
        $c.util.getComponent("ipt_isurEngNm2").setStyle("background", "#e2e2e2");
        $("#ipt_isurEngNm2").attr("onfocus", "this.blur()");
    } else {
        if (temp === "7") {
            $c.util.getComponent('ipt_isurEngNm2').setValue("");
            (($c.util.getComponent('ipt_isurEngNm2')) && ($c.util.getComponent('ipt_isurEngNm2')).setReadOnly ? ($c.util.getComponent('ipt_isurEngNm2')).setReadOnly((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
            $c.util.getComponent("ipt_isurEngNm2").setStyle("background", "#ffffff");
            $("#ipt_isurEngNm2").attr("onfocus", "");
            $c.util.getComponent("ipt_isurEngNm2").focus();
        } else {
            if (temp === "") {
                $c.util.getComponent('ipt_isurEngNm2').setValue("");
                (($c.util.getComponent('ipt_isurEngNm2')) && ($c.util.getComponent('ipt_isurEngNm2')).setReadOnly ? ($c.util.getComponent('ipt_isurEngNm2')).setReadOnly((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
                $c.util.getComponent("ipt_isurEngNm2").setStyle("background", "#e2e2e2");
                $("#ipt_isurEngNm2").attr("onfocus", "this.blur()");
            }
        }
    }
};

