 * @description check Usr Id Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.checkUsrIdDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_message').setValue(result.message);
    $("input[name='newYn']").val(result.newYn);
    $c.util.getComponent('ipt_oldIntegUsrId').setValue(SendForm.integ_usr_id.value);
    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
};

/**
 * @method
 * @name checkUsrId
 * @description check Usr Id 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkUsrId = async function () {
    const r = await scwin.tx_fn_checkUsrId();
    try {
        scwin.checkUsrIdDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldinf05000.fn_checkUsrId' });
    }
    return r;
};
